def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    tests = [
        fmt([5]),
        fmt([1, 2, 2, 2, 3, 3]),
        fmt([1, 10, 20]),
        fmt([7, 7, 7, 7]),
        fmt([1, 10**9]),
        fmt([1, 2, 3, 4, 5, 6, 7]),
        fmt([10**9, 1, 10**9, 1, 10**9]),
    ]
    for n in (2, 3, 4, 5, 6, 7):
        for hi in (3, 10, 100):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    for _ in range(4):
        tests.append(fmt([rng.randint(1, 10**9) for _ in range(rng.randint(5, 7))]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(2000)]))
    tests.append(fmt([rng.randint(1, 50) for _ in range(2000)]))
    tests.append(fmt(list(range(1, 2001))))
    tests.append(fmt([rng.choice([1, 10**9, 5 * 10**8]) for _ in range(2000)]))
    return tests

